CREATE TABLE public.crm_credentials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id), name text NOT NULL, key_hash text NOT NULL UNIQUE, key_prefix text NOT NULL, scopes text[] NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, window_start timestamptz NOT NULL DEFAULT now(), request_count integer NOT NULL DEFAULT 0);
GRANT SELECT,INSERT,UPDATE ON public.crm_credentials TO authenticated;
GRANT ALL ON public.crm_credentials TO service_role;
ALTER TABLE public.crm_credentials ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_keys_admin ON public.crm_credentials FOR ALL TO authenticated USING (tenant_id IN (SELECT private.my_tenants(ARRAY['tenant_admin']::public.app_role[]))) WITH CHECK (tenant_id IN (SELECT private.my_tenants(ARRAY['tenant_admin']::public.app_role[])) AND created_by=auth.uid());
CREATE TABLE public.crm_external_ids (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id), source_system text NOT NULL, entity_type text NOT NULL CHECK(entity_type IN ('leads','contacts','organizations','opportunities','properties','tasks','enquiries')), external_id text NOT NULL, entity_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,source_system,entity_type,external_id), UNIQUE(tenant_id,source_system,entity_type,entity_id));
GRANT SELECT ON public.crm_external_ids TO authenticated;
GRANT ALL ON public.crm_external_ids TO service_role;
ALTER TABLE public.crm_external_ids ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_refs_admin ON public.crm_external_ids FOR SELECT TO authenticated USING(tenant_id IN (SELECT private.my_tenants(ARRAY['tenant_admin','sales_manager']::public.app_role[])));
CREATE TABLE public.crm_owner_mappings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id), source_system text NOT NULL, external_owner_id text NOT NULL, user_id uuid NOT NULL, UNIQUE(tenant_id,source_system,external_owner_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_owner_mappings TO authenticated;
GRANT ALL ON public.crm_owner_mappings TO service_role;
ALTER TABLE public.crm_owner_mappings ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_owners_admin ON public.crm_owner_mappings FOR ALL TO authenticated USING(tenant_id IN (SELECT private.my_tenants(ARRAY['tenant_admin']::public.app_role[]))) WITH CHECK(tenant_id IN (SELECT private.my_tenants(ARRAY['tenant_admin']::public.app_role[])));
CREATE FUNCTION private.crm_owner_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.memberships WHERE tenant_id=NEW.tenant_id AND user_id=NEW.user_id AND status='active' AND role IN ('tenant_admin','sales_manager','sales_rep')) THEN RAISE EXCEPTION 'Owner must be an active seller in this workspace'; END IF; RETURN NEW; END $$;
CREATE TRIGGER crm_owner_guard BEFORE INSERT OR UPDATE ON public.crm_owner_mappings FOR EACH ROW EXECUTE FUNCTION private.crm_owner_guard();
ALTER TABLE public.leads ADD CONSTRAINT crm_lead_tenant_id UNIQUE(tenant_id,id);
ALTER TABLE public.contacts ADD CONSTRAINT crm_contact_tenant_id UNIQUE(tenant_id,id);
ALTER TABLE public.properties ADD CONSTRAINT crm_property_tenant_id UNIQUE(tenant_id,id);
ALTER TABLE public.opportunities ADD CONSTRAINT crm_opportunity_tenant_id UNIQUE(tenant_id,id);
CREATE TABLE public.enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id), lead_id uuid NOT NULL, property_id uuid NOT NULL, contact_id uuid, opportunity_id uuid, source_system text NOT NULL, external_id text NOT NULL, message text, budget numeric, timeline text, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','qualified','closed')), custom_fields jsonb NOT NULL DEFAULT '{}', created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,source_system,external_id), FOREIGN KEY(tenant_id,lead_id) REFERENCES public.leads(tenant_id,id), FOREIGN KEY(tenant_id,property_id) REFERENCES public.properties(tenant_id,id), FOREIGN KEY(tenant_id,contact_id) REFERENCES public.contacts(tenant_id,id), FOREIGN KEY(tenant_id,opportunity_id) REFERENCES public.opportunities(tenant_id,id));
GRANT SELECT,UPDATE ON public.enquiries TO authenticated;
GRANT ALL ON public.enquiries TO service_role;
ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY enquiry_read ON public.enquiries FOR SELECT TO authenticated USING (tenant_id IN (SELECT private.my_tenants()));
CREATE POLICY enquiry_edit ON public.enquiries FOR UPDATE TO authenticated USING(tenant_id IN (SELECT private.my_tenants(ARRAY['tenant_admin','sales_manager','ops_coordinator']::public.app_role[]))) WITH CHECK(tenant_id IN (SELECT private.my_tenants(ARRAY['tenant_admin','sales_manager','ops_coordinator']::public.app_role[])));
CREATE TRIGGER enquiry_updated BEFORE UPDATE ON public.enquiries FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TABLE public.crm_webhooks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id), name text NOT NULL, url text NOT NULL, signing_secret text NOT NULL, events text[] NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL);
GRANT SELECT(id,tenant_id,name,url,events,enabled,created_at,created_by),UPDATE(enabled) ON public.crm_webhooks TO authenticated;
GRANT ALL ON public.crm_webhooks TO service_role;
ALTER TABLE public.crm_webhooks ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_hooks_admin ON public.crm_webhooks FOR ALL TO authenticated USING(tenant_id IN (SELECT private.my_tenants(ARRAY['tenant_admin']::public.app_role[]))) WITH CHECK(tenant_id IN (SELECT private.my_tenants(ARRAY['tenant_admin']::public.app_role[])));
CREATE TABLE public.crm_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id), webhook_id uuid NOT NULL REFERENCES public.crm_webhooks(id), event_id uuid NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','delivered','failed')), attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz, last_status integer, last_error text, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, UNIQUE(webhook_id,event_id));
GRANT SELECT ON public.crm_deliveries TO authenticated;
GRANT ALL ON public.crm_deliveries TO service_role;
ALTER TABLE public.crm_deliveries ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_delivery_admin ON public.crm_deliveries FOR SELECT TO authenticated USING(tenant_id IN (SELECT private.my_tenants(ARRAY['tenant_admin']::public.app_role[])));
CREATE INDEX crm_delivery_pending ON public.crm_deliveries(next_attempt_at) WHERE status IN ('pending','sending');
CREATE INDEX enquiry_lead ON public.enquiries(tenant_id,lead_id);
CREATE FUNCTION private.crm_external_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE ok boolean; BEGIN EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE tenant_id=$1 AND id=$2)',NEW.entity_type) INTO ok USING NEW.tenant_id,NEW.entity_id; IF NOT ok THEN RAISE EXCEPTION 'External reference target not in workspace'; END IF; RETURN NEW; END $$;
CREATE TRIGGER crm_external_guard BEFORE INSERT OR UPDATE ON public.crm_external_ids FOR EACH ROW EXECUTE FUNCTION private.crm_external_guard();
CREATE FUNCTION private.crm_outbox() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE eid uuid:=gen_random_uuid(); et text; tid uuid; body jsonb; BEGIN tid:=NEW.tenant_id; et:=TG_TABLE_NAME||'.'||CASE WHEN TG_OP='INSERT' THEN 'created' ELSE 'updated' END; body:=jsonb_build_object('id',eid,'type',et,'tenant_id',tid,'occurred_at',now(),'data',to_jsonb(NEW)); INSERT INTO public.crm_deliveries(tenant_id,webhook_id,event_id,event_type,payload) SELECT tid,id,eid,et,body FROM public.crm_webhooks WHERE tenant_id=tid AND enabled AND et=ANY(events); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION private.crm_outbox() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['leads','contacts','organizations','opportunities','properties','tasks','enquiries'] LOOP EXECUTE format('CREATE TRIGGER crm_outbox AFTER INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION private.crm_outbox()',t); END LOOP; END $$;
CREATE FUNCTION public.crm_authenticate(_hash text) RETURNS SETOF public.crm_credentials LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RETURN QUERY UPDATE public.crm_credentials SET request_count=CASE WHEN window_start < now()-interval '1 minute' THEN 1 ELSE request_count+1 END, window_start=CASE WHEN window_start < now()-interval '1 minute' THEN now() ELSE window_start END WHERE key_hash=_hash AND revoked_at IS NULL AND expires_at>now() RETURNING *; END $$;
REVOKE ALL ON FUNCTION public.crm_authenticate(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.crm_authenticate(text) TO service_role;
CREATE FUNCTION public.crm_claim_deliveries(_tenant uuid DEFAULT NULL) RETURNS SETOF public.crm_deliveries LANGUAGE sql SET search_path=public AS $$ UPDATE public.crm_deliveries SET status='sending',attempts=attempts+1,locked_until=now()+interval '2 minutes' WHERE id IN (SELECT id FROM public.crm_deliveries WHERE (_tenant IS NULL OR tenant_id=_tenant) AND attempts<8 AND ((status='pending' AND next_attempt_at<=now()) OR (status='sending' AND locked_until<now())) ORDER BY next_attempt_at FOR UPDATE SKIP LOCKED LIMIT 5) RETURNING *; $$;
REVOKE ALL ON FUNCTION public.crm_claim_deliveries(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.crm_claim_deliveries(uuid) TO service_role;
CREATE FUNCTION public.crm_create_enquiry(_tenant uuid,_actor uuid,_body jsonb,_score integer) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$ DECLARE e public.enquiries; lid uuid; pid uuid; em text; ph text; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(_tenant::text||(_body->>'source_system'),0)); SELECT * INTO e FROM public.enquiries WHERE tenant_id=_tenant AND source_system=_body->>'source_system' AND external_id=_body->>'external_id'; IF FOUND THEN RETURN jsonb_build_object('enquiry',to_jsonb(e),'replayed',true); END IF; IF _body ? 'property_id' THEN pid:=(_body->>'property_id')::uuid; ELSE SELECT entity_id INTO pid FROM public.crm_external_ids WHERE tenant_id=_tenant AND source_system=_body->>'source_system' AND entity_type='properties' AND external_id=_body->>'property_external_id'; END IF; IF NOT EXISTS(SELECT 1 FROM public.properties WHERE tenant_id=_tenant AND id=pid) THEN RAISE EXCEPTION 'Property not found'; END IF; em:=nullif(lower(trim(_body->>'email')),''); ph:=nullif(_body->>'phone',''); IF _body ? 'lead_id' THEN SELECT id INTO lid FROM public.leads WHERE tenant_id=_tenant AND id=(_body->>'lead_id')::uuid; IF lid IS NULL THEN RAISE EXCEPTION 'Lead not found'; END IF; ELSE SELECT id INTO lid FROM public.leads WHERE tenant_id=_tenant AND ((em IS NOT NULL AND email=em) OR (ph IS NOT NULL AND phone=ph)) ORDER BY created_at LIMIT 1; IF lid IS NULL THEN INSERT INTO public.leads(tenant_id,full_name,email,phone,source,status,score,notes,created_by,owner_id,custom_fields) VALUES(_tenant,_body->>'full_name',em,ph,_body->>'source_system','new',_score,_body->>'message',_actor,NULL,coalesce(_body->'custom_fields','{}')) RETURNING id INTO lid; INSERT INTO public.tasks(tenant_id,title,kind,status,lead_id,created_by) VALUES(_tenant,'Assign & contact: '||(_body->>'full_name'),'call','open',lid,_actor); END IF; END IF; INSERT INTO public.enquiries(tenant_id,lead_id,property_id,source_system,external_id,message,budget,timeline,custom_fields,created_by) VALUES(_tenant,lid,pid,_body->>'source_system',_body->>'external_id',_body->>'message',(_body->>'budget')::numeric,_body->>'timeline',coalesce(_body->'custom_fields','{}'),_actor) RETURNING * INTO e; INSERT INTO public.crm_external_ids(tenant_id,source_system,entity_type,external_id,entity_id) VALUES(_tenant,e.source_system,'enquiries',e.external_id,e.id); RETURN jsonb_build_object('enquiry',to_jsonb(e),'replayed',false); END $$;
REVOKE ALL ON FUNCTION public.crm_create_enquiry(uuid,uuid,jsonb,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.crm_create_enquiry(uuid,uuid,jsonb,integer) TO service_role;